SELECT p.id AS position_id, s.id, s.interval_code, s.decision, s.original_decision, s.generated_at, s.created_at, s.latest_price, s.total_score, s.confluence_status, s.confluence_higher_decision FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.symbol=p.symbol AND s.generated_at BETWEEN p.opened_at AND p.closed_at WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.generated_at LIMIT 400;